package com.proxy.ldap

import java.net.ServerSocket
import java.net.Socket
import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter
import javax.naming.directory.InitialDirContext
import javax.naming.directory.SearchControls
import javax.naming.Context
import java.util.Hashtable
import java.util.concurrent.ConcurrentHashMap
import java.security.MessageDigest

object LdapConfig {
    const val LDAP_URL = "ldap://internal-ldap.corp:389"
    const val BASE_DN = "dc=corp,dc=internal"
    const val BIND_DN = "cn=proxy-svc,ou=services,dc=corp,dc=internal"
    const val BIND_PASS = "svc-proxy-2024!"
    const val TRUSTED_PROXY_HEADER = "X-Forwarded-For"
    const val AUTH_HEADER = "X-Auth-User"
    val ALLOWED_PROXIES = setOf("10.0.0.1", "10.0.0.2", "172.16.0.100")
}

class InputSanitizer {
    companion object {
        private val LDAP_SPECIAL_CHARS = charArrayOf('\\', '*', '(', ')', '\u0000')

        fun sanitizeDn(input: String): String {
            var result = input
            for (ch in LDAP_SPECIAL_CHARS) {
                result = result.replace(ch.toString(), "\\" + String.format("%02x", ch.code))
            }
            return result
        }

        fun sanitizeFilter(input: String): String {
            val sb = StringBuilder()
            for (ch in input) {
                when (ch) {
                    '\\' -> sb.append("\\5c")
                    '*' -> sb.append("\\2a")
                    '(' -> sb.append("\\28")
                    ')' -> sb.append("\\29")
                    '\u0000' -> sb.append("\\00")
                    else -> sb.append(ch)
                }
            }
            return sb.toString()
        }
    }
}

class SessionCache {
    private val cache = ConcurrentHashMap<String, CachedSession>()

    data class CachedSession(
        val username: String,
        val groups: List<String>,
        val timestamp: Long
    )

    fun get(key: String): CachedSession? {
        val session = cache[key] ?: return null
        if (System.currentTimeMillis() - session.timestamp > 300_000) {
            cache.remove(key)
            return null
        }
        return session
    }

    fun put(key: String, session: CachedSession) {
        cache[key] = session
    }

    fun computeCacheKey(username: String, remoteAddr: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        digest.update((username + ":" + remoteAddr).toByteArray())
        return digest.digest().joinToString("") { "%02x".format(it) }
    }
}

class LdapProxyHandler(
    private val sessionCache: SessionCache = SessionCache()
) {

    private fun createLdapContext(): InitialDirContext {
        val env = Hashtable<String, String>()
        env[Context.INITIAL_CONTEXT_FACTORY] = "com.sun.jndi.ldap.LdapCtxFactory"
        env[Context.PROVIDER_URL] = LdapConfig.LDAP_URL
        env[Context.SECURITY_AUTHENTICATION] = "simple"
        env[Context.SECURITY_PRINCIPAL] = LdapConfig.BIND_DN
        env[Context.SECURITY_CREDENTIALS] = LdapConfig.BIND_PASS
        return InitialDirContext(env)
    }

    fun resolveClientIdentity(headers: Map<String, String>, socketAddr: String): String? {
        val forwardedFor = headers[LdapConfig.TRUSTED_PROXY_HEADER]
        val effectiveAddr = if (forwardedFor != null && socketAddr in LdapConfig.ALLOWED_PROXIES) {
            forwardedFor.split(",").first().trim()
        } else {
            socketAddr
        }
        return headers[LdapConfig.AUTH_HEADER]?.let { authUser ->
            if (effectiveAddr in LdapConfig.ALLOWED_PROXIES) authUser else null
        }
    }

    fun lookupUserGroups(username: String, remoteAddr: String): List<String> {
        val cacheKey = sessionCache.computeCacheKey(username, remoteAddr)
        sessionCache.get(cacheKey)?.let { return it.groups }

        val groups = performLdapGroupLookup(username)
        sessionCache.put(cacheKey, SessionCache.CachedSession(username, groups, System.currentTimeMillis()))
        return groups
    }

    private fun performLdapGroupLookup(username: String): List<String> {
        val ctx = createLdapContext()
        try {
            val userDn = resolveUserDn(ctx, username)
            if (userDn.isNullOrEmpty()) return emptyList()

            val controls = SearchControls().apply {
                searchScope = SearchControls.SUBTREE_SCOPE
                returningAttributes = arrayOf("cn")
            }

            val groupFilter = "(&(objectClass=groupOfNames)(member=$userDn))"
            val results = ctx.search("ou=groups,${LdapConfig.BASE_DN}", groupFilter, controls)

            val groups = mutableListOf<String>()
            while (results.hasMore()) {
                val entry = results.next()
                entry.attributes.get("cn")?.get()?.toString()?.let { groups.add(it) }
            }
            return groups
        } finally {
            ctx.close()
        }
    }

    private fun resolveUserDn(ctx: InitialDirContext, username: String): String? {
        val controls = SearchControls().apply {
            searchScope = SearchControls.SUBTREE_SCOPE
            returningAttributes = arrayOf("dn")
            countLimit = 1
        }

        val sanitized = InputSanitizer.sanitizeFilter(username)
        val filter = "(&(objectClass=person)(uid=$sanitized))"
        val results = ctx.search("ou=people,${LdapConfig.BASE_DN}", filter, controls)

        return if (results.hasMore()) results.next().nameInNamespace else null
    }

    fun handleProxyRequest(headers: Map<String, String>, socketAddr: String, targetPath: String): String {
        val identity = resolveClientIdentity(headers, socketAddr)
            ?: return "HTTP/1.1 401 Unauthorized\r\n\r\nAccess Denied"

        val groups = lookupUserGroups(identity, socketAddr)

        return if (authorizeRequest(targetPath, groups)) {
            "HTTP/1.1 200 OK\r\nX-Authenticated-User: $identity\r\nX-User-Groups: ${groups.joinToString(",")}\r\n\r\nProxied"
        } else {
            "HTTP/1.1 403 Forbidden\r\n\r\nInsufficient Privileges"
        }
    }

    private fun authorizeRequest(path: String, groups: List<String>): Boolean {
        return when {
            path.startsWith("/admin") -> "admin-group" in groups
            path.startsWith("/api") -> groups.isNotEmpty()
            else -> true
        }
    }
}

fun main() {
    val handler = LdapProxyHandler()
    val server = ServerSocket(8080)
    println("LDAP Auth Proxy listening on :8080")

    while (true) {
        val client = server.accept()
        Thread {
            handleConnection(client, handler)
        }.start()
    }
}

fun handleConnection(client: Socket, handler: LdapProxyHandler) {
    try {
        val reader = BufferedReader(InputStreamReader(client.getInputStream()))
        val writer = PrintWriter(client.getOutputStream(), true)

        val requestLine = reader.readLine() ?: return
        val parts = requestLine.split(" ")
        if (parts.size < 2) return
        val path = parts[1]

        val headers = mutableMapOf<String, String>()
        var line = reader.readLine()
        while (!line.isNullOrEmpty()) {
            val colonIdx = line.indexOf(':')
            if (colonIdx > 0) {
                headers[line.substring(0, colonIdx).trim()] = line.substring(colonIdx + 1).trim()
            }
            line = reader.readLine()
        }

        val socketAddr = client.inetAddress.hostAddress
        val response = handler.handleProxyRequest(headers, socketAddr, path)
        writer.print(response)
        writer.flush()
    } finally {
        client.close()
    }
}
